mapper.select:
SELECT R.RAW_DATA_ID, R.EXECUTION_ID, R.EXTERNAL_API_ID, A.API_NAME, R.REQUEST_SEQUENCE, R.CONTENT_TYPE, R.COLLECTED_AT FROM SCHED_COLLECT_RAW_DATA R INNER JOIN SCHED_EXTERNAL_API A ON R.EXTERNAL_API_ID = A.EXTERNAL_API_ID WHERE 1 = 1
AND A.API_NAME LIKE '%' || #{searchDto.apiName} || '%'
AND R.COLLECTED_AT >= #{startAt}
AND R.COLLECTED_AT < #{endAt}
ORDER BY R.COLLECTED_AT DESC, R.RAW_DATA_ID DESC OFFSET #{searchDto.offset} ROWS FETCH NEXT #{searchDto.size} ROWS ONLY

SELECT COUNT(*) FROM SCHED_COLLECT_RAW_DATA R INNER JOIN SCHED_EXTERNAL_API A ON R.EXTERNAL_API_ID = A.EXTERNAL_API_ID WHERE 1 = 1
AND A.API_NAME LIKE '%' || #{searchDto.apiName} || '%'
AND R.COLLECTED_AT >= #{startAt}
AND R.COLLECTED_AT < #{endAt}
